<?php $structures=$structures??[];$categories=$categories??[]; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee Structures | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f6f7fb;color:#172033}.wrap{max-width:1100px;margin:30px auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}input,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ccd1db;border-radius:8px;margin:6px 0 12px}button,a{padding:9px 13px;border:0;border-radius:8px;background:#172033;color:#fff;text-decoration:none}.actions{display:flex;gap:8px;flex-wrap:wrap}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:11px;border-bottom:1px solid #eee;text-align:left}.muted{color:#667085}</style></head><body><main class="wrap"><p><a href="/finance">← Finance</a></p><h1>Fee Structures</h1><p class="muted">Define reusable charges, publish them, then generate student invoices in one controlled batch.</p><div class="actions"><a href="/finance/fee-structures/create">Create structure</a></div><section class="card"><h2>Generate invoices</h2><form method="post" action="/finance/fee-structures/generate"><input type="hidden" name="_token" value="<?= htmlspecialchars((string)($_SESSION['_csrf']??''),ENT_QUOTES) ?>"><div class="grid"><div><label>Published structure</label><select name="fee_structure_id" required><?php foreach($structures as $s): if($s['status']!=='published')continue; ?><option value="<?= (int)$s['id'] ?>"><?= htmlspecialchars($s['name']) ?> — <?= number_format((float)$s['structure_total'],2) ?></option><?php endforeach; ?></select></div><div><label>Invoice date</label><input type="date" name="invoice_date" value="<?= date('Y-m-d') ?>" required></div><div><label>Due date</label><input type="date" name="due_date"></div><div><label>Invoice prefix</label><input name="invoice_prefix" value="FEE" maxlength="20" required></div></div><button type="submit">Generate invoices</button></form></section><section class="card"><table><thead><tr><th>Structure</th><th>Target class</th><th>Target stream</th><th>Items</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($structures as $s): ?><tr><td><?= htmlspecialchars($s['name']) ?></td><td><?= $s['target_class_id']===null?'All classes':(int)$s['target_class_id'] ?></td><td><?= $s['target_stream_id']===null?'All streams':(int)$s['target_stream_id'] ?></td><td><?= (int)$s['item_count'] ?></td><td>KES <?= number_format((float)$s['structure_total'],2) ?></td><td><?= htmlspecialchars(ucfirst($s['status'])) ?></td><td><?php if($s['status']==='draft'): ?><form method="post" action="/finance/fee-structures/publish"><input type="hidden" name="_token" value="<?= htmlspecialchars((string)($_SESSION['_csrf']??''),ENT_QUOTES) ?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button>Publish</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach;if(!$structures): ?><tr><td colspan="7" class="muted">No fee structures yet.</td></tr><?php endif; ?></tbody></table></section></main></body></html>
